<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue';
import type { PhotoMemory, PhotoGroupNote } from '../../../packages/contracts/src/index.js';
import { photoDate, photoPlaceName, photoGroupKey } from '../photos';
import AtlasIcon from './AtlasIcon.vue';
const props = defineProps<{ photos: PhotoMemory[]; start: string; notes: PhotoGroupNote[] }>();
const emit = defineEmits<{ close: []; edit: [photo: PhotoMemory]; map: [photo: PhotoMemory]; remove: [photo: PhotoMemory] }>();
const dialog = ref<HTMLDialogElement>(), index = ref(Math.max(0, props.photos.findIndex(p => p.mediaId === props.start))), photo = computed(() => props.photos[index.value]!);
const note = computed(() => props.notes.find(n => n.key === photoGroupKey(photo.value))?.note);
const previousFocus = document.activeElement as HTMLElement | null; let touchX = 0;
function move(direction: number) { index.value = Math.max(0, Math.min(props.photos.length - 1, index.value + direction)); }
function key(e: KeyboardEvent) { if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') { e.preventDefault(); move(e.key === 'ArrowRight' ? 1 : -1); } }
onMounted(() => dialog.value?.showModal()); onBeforeUnmount(() => { dialog.value?.close(); previousFocus?.focus({ preventScroll: true }); });
</script>
<template><dialog ref="dialog" class="photo-viewer" aria-label="照片浏览" @cancel.prevent="emit('close')" @keydown="key"><div v-if="photo" class="memory-viewer-layout"><header class="memory-viewer-top"><button class="memory-text-button" aria-label="关闭照片浏览" @click="emit('close')"><AtlasIcon name="close"/></button><span>{{ index + 1 }} / {{ photos.length }}</span><button class="memory-text-button" aria-label="补充照片信息" @click="emit('edit', photo)"><AtlasIcon name="edit"/></button></header><div class="memory-viewer-stage" @touchstart.passive="touchX = $event.touches[0]?.clientX || 0" @touchend.passive="Math.abs(($event.changedTouches[0]?.clientX || 0) - touchX) > 55 && move(($event.changedTouches[0]?.clientX || 0) > touchX ? -1 : 1)"><img :key="photo.mediaId" :src="photo.media.previewUrl" :alt="photoPlaceName(photo.place)" :width="photo.media.width" :height="photo.media.height"></div><section class="memory-viewer-info"><h2>{{ photoPlaceName(photo.place) }}</h2><p class="memory-viewer-date">{{ photoDate(photo.takenOn) }}</p><p v-if="photo.note" class="memory-viewer-note">{{ photo.note }}</p><p v-if="note" class="memory-viewer-group-note">这一组 · {{ note }}</p><div class="memory-viewer-actions"><button class="memory-text-button" @click="photo.place?.position ? emit('map', photo) : emit('edit', photo)"><AtlasIcon :name="photo.place?.position ? 'map' : 'pin'"/>{{ photo.place?.position ? '在地图上看' : '补充拍摄地点' }}</button><div class="memory-viewer-arrows"><button class="memory-text-button" aria-label="上一张照片" :disabled="index === 0" @click="move(-1)"><AtlasIcon name="back"/></button><button class="memory-text-button" aria-label="下一张照片" :disabled="index === photos.length - 1" @click="move(1)"><AtlasIcon name="chevronRight"/></button></div></div><button class="memory-text-button photo-remove-button" @click="emit('remove', photo)">移出回忆</button><RouterLink v-if="photo.diaryId" :to="'/diaries/' + photo.diaryId" class="memory-viewer-sample">查看原日记</RouterLink></section></div></dialog></template>
